import impl


def test_large_attempt_count_stays_finite_and_bounded():
    attempts, base, cap = 2000, 1.0, 30.0
    result = impl.schedule(attempts, base, cap, lambda u: u)

    assert len(result) == attempts
    for d in result:
        assert math.isfinite(d)
        assert 0.0 <= d <= cap + 1e-12

    # Once base * 2**i has clearly exceeded cap, every later ceiling must be exactly cap.
    assert result[-1] == pytest_approx(cap)
    assert result[100] == pytest_approx(cap)


def pytest_approx(value, tol=1e-9):
    class _Approx:
        def __eq__(self, other):
            return abs(other - value) <= tol
    return _Approx()

