def test_week_number_never_zero_and_within_bounds():
    for year in (1, 100, 1900, 2000, 2020, 2021, 2023, 2024, 9999):
        start = date(year, 1, 1)
        end = date(year, 12, 31)
        d = start
        while d <= end:
            _, week_number, weekday = impl.to_iso_week_date(d.year, d.month, d.day)
            assert 1 <= week_number <= 53, f"{d.isoformat()} produced week_number={week_number}"
            assert 1 <= weekday <= 7, f"{d.isoformat()} produced weekday={weekday}"
            d += timedelta(days=1)

