def test_week_53_and_52_year_lengths():
    max_week_by_week_year = {}
    d = date(2019, 12, 1)
    end = date(2022, 1, 15)
    while d <= end:
        week_year, week_number, _ = impl.to_iso_week_date(d.year, d.month, d.day)
        max_week_by_week_year[week_year] = max(
            max_week_by_week_year.get(week_year, 0), week_number
        )
        d += timedelta(days=1)

    assert max_week_by_week_year[2020] == 53
    assert max_week_by_week_year[2021] == 52

